		InstrumentID: "M-1", Number: "C-1", CalDate: "2026-09-01",
		Expiry: "2027-09-01", Method: "m", Error: 0, Summary: "s",
	})
	r, _ = l.Review("M-1")
	if !r.CanUse {
		t.Fatalf("补录合格证书并在用后应可使用，得到 %v", r.Reasons)
