		t.Fatalf("历史拒绝原因被改写：保存=%v 现在=%v", frozen, r.Rejections[0].Reasons)
	}
	if r.Latest == nil || r.Latest.Number != "C-1" {
		t.Fatal("核对视图应包含最近证书")
	}

