func (l *Ledger) UsageRecords() []UsageRecord {
	out := append([]UsageRecord(nil), l.data.Usage...)
	instants := make([]time.Time, len(out))
	parsed := make([]bool, len(out))
	for i := range out {
		out[i].Reasons = cloneReasons(out[i].Reasons)
		instants[i], parsed[i] = parseUsageInstant(out[i].RequestedAt)
	}
	sort.SliceStable(out, func(i, j int) bool {
		// 稳定排序：实际时刻、器具编号都相同时（同一器具同一时刻的多次
		// 申请，或 Z 与零偏移等同义写法），比较器返回 false 以保留它们
		// 在台账中的原有次序，不依赖时间的文字形式再分先后。
		switch pi, pj := parsed[i], parsed[j]; {
		case pi && pj:
			if !instants[i].Equal(instants[j]) {
				return instants[i].Before(instants[j])
			}
		case !pi && !pj:
			// 正常台账不会出现无法解析的时间；两条都无法解析时按原文字
			// 兜底，保持可确定的先后。
			if out[i].RequestedAt != out[j].RequestedAt {
				return out[i].RequestedAt < out[j].RequestedAt
			}
		default:
			// 仅一条无法解析时，让时刻可解析的已知记录排在前面，
			// 保证混合情况下的排序仍然完全确定。
			return pi
		}
		if out[i].InstrumentID != out[j].InstrumentID {
			return out[i].InstrumentID < out[j].InstrumentID
		}
		return false
	})
	return out
}

